    %softmax = "stablehlo.divide"(%exp, %sum_bcast) : (tensor<6x16x7x7xf32>, tensor<6x7x7xf32>) -> tensor<6x16x7x7xf32>

    // Step 4: Subtract parameter %arg2 (bias) from softmax result
    // Broadcast bias to match shape
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = dense<[1]> : tensor<1xi64>
    } : (tensor<16xf32>) -> tensor<6x16x7x7xf32>

    %sub_bias = "stablehlo.subtract"(%softmax, %bias_bcast) : (tensor<6x16x7x7xf32>, tensor<6x16x7x7xf32>) -> tensor<6x16x7x7xf32>

    // Step 5: Swish activation: sigmoid * x
    // Compute sigmoid: 1 / (1 + exp(-x))
    %neg_x = "stablehlo.negate"(%sub_bias) : (tensor<6x16x7x7xf32>) -> tensor<6x16x7x7xf32>
    %exp_neg_x = "stablehlo.exponential"(%neg_x) : (tensor<6x16x7x7xf32>) -> tensor<6x16x7x7xf32>
    %one = "stablehlo.constant"() {value = dense<1.0 : tensor<16xf32>} : () -> tensor<16xf32>
    %denominator = "stablehlo.add"(%one, %exp_neg_x) : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>
    %sigmoid = "stablehlo.divide"(%one, %denominator) : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>

    // Multiply sigmoid * x (which is %sub_bias)
    %swish = "stablehlo.multiply"(%sigmoid, %sub_bias) : (tensor<6x16x7x7xf32>, tensor<6x16x7x7xf32>) -> tensor<6x16x7x7xf32>

    // Step 6: Max over channels (dim=1)
    // Compute max along channel dimension
    %max_channels = "stablehlo.reduce"(%swish, "stablehlo.constant"() {value = dense< -inf : tensor<16xf32>} : () -> tensor<16xf32>) {
      dimensions = dense<[1]> : tensor<1xi64>,
      init_value = "stablehlo.constant"() {value = dense< -inf : tensor<16xf32>} : () -> tensor<16xf32>
    } : (tensor<6x16x7x7xf32>, tensor<16xf32>) -> tensor<6x7x7xf32>

    // The result is a tensor of shape [6,7,7], as max over channels
    return %max_channels : tensor<6x7x7xf32>
  }
}

