func.func @main(
    %arg0: tensor<7x8x3x3xf32>,        // input tensor
    %arg1: tensor<7xf32>,               // conv.bias
    %arg2: tensor<7xf32>,               // bn.weight
    %arg3: tensor<7xf32>,               // bn.bias
    %arg4: tensor<6x8x6x6xf32>          // conv input (forward input)
  ) -> tensor<6x7x4x4xf32> {
    // Step 1: Perform convolution
    %conv_result = "stablehlo.convolution"(%arg4, %arg0) {
      // dimension_numbers: input batch, spatial dims, feature dims
      dimension_numbers = #stablehlo.conv<[
        b, 0, 1, f
      ]x[
        0, 1, i, o
      ]->[
        b, 0, 1, f
      ]>,
      window_strides = dense<[1, 1]> : tensor<2xi64>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64,
      precision_config = []
    } : (tensor<6x8x6x6xf32>, tensor<7x3x3xf32>) -> tensor<6x7x4x4xf32>

    // Step 2: Broadcast bn.weight, bn.bias to match conv output shape
    // shape of conv output: [6,7,4,4]
    // broadcast bn.weight and bn.bias from shape [7] to [6,7,4,4]
    %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = dense<[1, 2, 3]> : tensor<3xi64>
    } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {
      broadcast_dimensions = dense<[1, 2, 3]> : tensor<1xi64>
    } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

    // Step 3: Add bias to convolution result
    %conv_bias_add = "stablehlo.add"(%conv_result, %bn_bias_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // Step 4: Batch normalization
    // Compute mean over axes [0,2,3]
    %axes_mean = "stablehlo.range"() {iota_dimension = 0 : i64} : () -> tensor<1xi64>
    %axes_mean2 = "stablehlo.range"() {iota_dimension = 2 : i64} : () -> tensor<1xi64>
    %axes_mean3 = "stablehlo.range"() {iota_dimension = 3 : i64} : () -> tensor<1xi64>
    // Concatenate axes for reduction: [0, 2, 3]
    %mean_axes = "stablehlo.concatenate"(%axes_mean, %axes_mean2, %axes_mean3) {
      dimension = 0 : i64
    } : (tensor<1xi64>, tensor<1xi64>, tensor<1xi64>) -> tensor<3xi64>

    // Compute mean
    %sum = "stablehlo.reduce"(%conv_bias_add, %arg3) {
      dimensions = %mean_axes,
      body = ^bb0(%x: tensor<6x7x4x4xf32>, %y: tensor<6x7x4x4xf32>):
        %add = "stablehlo.add"(%x, %y) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
        "stablehlo.return"(%add) : (tensor<6x7x4x4xf32>) -> ()
    } : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    // Divide sum by number of elements in axes [0,2,3]
    // shape of sum: [6,7,4,4]
    // number of elements: 6*4*4=96
    %num_elements = "stablehlo.constant"() {value = dense<96> : tensor<1xi64>} : () -> tensor<1xi64>
    %mean = "stablehlo.divide"(%sum, %num_elements) : (tensor<6x7x4x4xf32>, tensor<1xi64>) -> tensor<6x7x4x4xf32>

    // Compute variance
    // Broadcast mean to match conv output shape
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<[0, 2, 3]> : tensor<3xi64>
    } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    // Subtract mean
    %centered = "stablehlo.subtract"(%conv_bias_add, %mean_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    // Square centered
    %centered_sq = "stablehlo.multiply"(%centered, %centered) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    // Sum squared deviations
    %sum_sq = "stablehlo.reduce"(%centered_sq, %arg3) {
      dimensions = %mean_axes,
      body = ^bb1(%x: tensor<6x7x4x4xf32>, %y: tensor<6x7x4x4xf32>):
        %add = "stablehlo.add"(%x, %y) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
        "stablehlo.return"(%add) : (tensor<6x7x4x4xf32>) -> ()
    } : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    // Divide by number of elements to get variance
    %variance = "stablehlo.divide"(%sum_sq, %num_elements) : (tensor<6x7x4x4xf32>, tensor<1xi64>) -> tensor<6x7x4x4xf32>

    // Step 5: Normalize
    // Broadcast mean and variance
    %mean_bcast2 = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<[0, 2, 3]> : tensor<3xi64>
    } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %variance_bcast = "stablehlo.broadcast_in_dim"(%variance) {
      broadcast_dimensions = dense<[0, 2, 3]> : tensor<3xi64>
    } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    // Compute stddev
    %epsilon = "stablehlo.constant"() {value = dense<1e-5> : tensor<1xf32>} : () -> tensor<1xf32>
    %variance_plus_epsilon = "stablehlo.add"(%variance_bcast, %epsilon) : (tensor<6x7x4x4xf32>, tensor<1xf32>) -> tensor<6x7x4x4xf32>
    %stddev = "stablehlo.sqrt"(%variance_plus_epsilon) : (tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    // Normalize
    %centered_div = "stablehlo.divide"(%centered, %stddev) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    // Scale normalized
    %scaled = "stablehlo.multiply"(%centered_div, %bn_weight_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>)

// Complete StableHLO program implementing the described convolution + Mish activation pipeline
// Entry function signature:
// func.func @main(%arg0: tensor<7x6x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x6x8x8xf32>) -> tensor<6x7x6x6xf32>

module {
  func.func @main(%arg0: tensor<7x6x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x6x8x8xf32>) -> tensor<6x7x6x6xf32> {
    // Step 1: Perform convolution
    %conv_result = "stablehlo.convolution"(%arg2, %arg0) {
      // dimension numbers for NCHW to NHWC style
      dimension_numbers = #stablehlo.conv<
        input_batch_dimension = 0,
        input_feature_dimension = 1,
        input_spatial_dimensions = [2, 3],
        kernel_input_feature_dimension = 2,
        kernel_output_feature_dimension = 3,
        kernel_spatial_dimensions = [0, 1],
        output_batch_dimension = 0,
        output_feature_dimension = 1,
        output_spatial_dimensions = [2, 3]
      >,
      window_strides = dense<[1, 1]> : tensor<2xi64>,
      padding = dense<[[0,0],[0,0]]> : tensor<2x2xi64>,
      base_dilations = dense<[1, 1]> : tensor<2xi64>,
      window_dilations = dense<[1, 1]> : tensor<2xi64>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64,
      precision_config = []
    } : tensor<7x6x3x3xf32> -> tensor<7x6x3x3xf32>

    // Step 2: Reshape conv output to NHWC for Mish
    // Input shape: [7,6,3,3], output shape: [7,6,3,3]
    // We want to permute to [0, 2, 3, 1] (NHWC)
    %perm = "stablehlo.constant"() {value = dense<[0, 2, 3, 1]> : tensor<4xi64>} : () -> tensor<4xi64>
    %transposed = "stablehlo.transpose"(%conv_result) {permutation = %perm} : tensor<7x6x3x3xf32> -> tensor<7x3x3x6>

    // Step 3: Reshape to [6,7,6,6] (target shape)
    // First, get shape of transposed tensor
    %shape_transposed = "stablehlo.shape_of"(%transposed) : (tensor<7x3x3x6>) -> tensor<4xi64>
    // Extract shape dims
    %dim0 = "stablehlo.get_dimension_size"(%shape_transposed) {dimension = 0} : (tensor<4xi64>) -> tensor<i32>
    %dim1 = "stablehlo.get_dimension_size"(%shape_transposed) {dimension = 1} : (tensor<4xi64>) -> tensor<i32>
    %dim2 = "stablehlo.get_dimension_size"(%shape_transposed) {dimension = 2} : (tensor<4xi64>) -> tensor<i32>
    %dim3 = "stablehlo.get_dimension_size"(%shape_transposed) {dimension = 3} : (tensor<4xi64>) -> tensor<i32>
    // Compose new shape: [6,7,6,6]
    %new_shape = "stablehlo.constant"() {value = dense<[6,7,6,6]> : tensor<4xi64>} : () -> tensor<4xi64>
    // Reshape
    %reshaped = "stablehlo.reshape"(%transposed, %new_shape) : tensor<7x3x3x6> -> tensor<6x7x6x6xf32>

    // Step 4: Apply Mish activation: mish(x) = x * tanh(softplus(x))
    // Compute softplus: log(1 + exp(x))
    %one = "stablehlo.constant"() {value = dense<1.0 : f32> : tensor<f32>} : () -> tensor<f32>
    %exp_x = "stablehlo.exponential"(%reshaped) : tensor<6x7x6x6xf32> -> tensor<6x7x6x6xf32>
    %add_exp_one = "stablehlo.add"(%exp_x, %one) : tensor<6x7x6x6xf32> -> tensor<6x7x6x6xf32>
    %log_part = "stablehlo.log"(%add_exp_one) : tensor<6x7x6x6xf32> -> tensor<6x7x6x6xf32>
    // Compute tanh(softplus(x))
    %tanh = "stablehlo.tanh"(%log_part) : tensor<6x7x6x6xf32> -> tensor<6x7x6x6xf32>
    // Multiply x * tanh(...)
    %mish = "stablehlo.multiply"(%reshaped, %tanh) : tensor<6x7x6x6xf32> -> tensor<6x7x6x6xf32>

    // Step 5: Return the Mish-activated tensor
    return %mish : tensor<6x7x6x6xf32>
  }
}

