func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x8x8xf32>) -> tensor<6xf32> {
    // Step 1: Convolution
    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      // Dimension numbers for NCHW to NCHW convolution
      dimension_numbers = #stablehlo.conv<[
        // input batch, spatial dims, input channels
        input_batch_dimension = 0,
        input_feature_dimension = 1,
        input_spatial_dimensions = [2, 3],
        kernel_input_feature_dimension = 1,
        kernel_output_feature_dimension = 0,
        kernel_spatial_dimensions = [2, 3],
        output_batch_dimension = 0,
        output_feature_dimension = 1,
        output_spatial_dimensions = [2, 3]
      ]>,
      feature_group_count = 1 : si64,
      batch_group_count = 1 : si64,
      // Use default precision config
      precision_config = []
    } : (tensor<6x8x8x8xf32>, tensor<7x3x3xf32>) -> tensor<6x8x8x8xf32>

    // Step 2: Average Pooling with kernel size 4x4
    // Calculate padding: no padding, so shape remains same
    %pool = "stablehlo.reduce_window"(%conv, %zero) {
      window_dimensions = dense<[4, 4]> : tensor<2xi64>,
      window_strides = dense<[4, 4]> : tensor<2xi64>,
      base_dilations = dense<[1, 1]> : tensor<2xi64>,
      window_dilations = dense<[1, 1]> : tensor<2xi64>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      body = ^bb0(%acc: tensor<8x8xf32>, %x: tensor<8x8xf32>):
        %add = "stablehlo.add"(%acc, %x) : (tensor<8x8xf32>, tensor<8x8xf32>) -> tensor<8x8xf32>
        "stablehlo.return"(%add) : (tensor<8x8xf32>) -> ()
    } : (tensor<6x8x8x8xf32>, tensor<6x8x8x8xf32>) -> tensor<6x8x8x8xf32>

    // Step 3: Apply sigmoid (via 1 / (1 + exp(-x)))
    // Compute -x
    %neg_x = "stablehlo.negate"(%pool) : (tensor<6x8x8x8xf32>) -> tensor<6x8x8x8xf32>
    // exp(-x)
    %exp_neg_x = "stablehlo.exponential"(%neg_x) : (tensor<6x8x8x8xf32>) -> tensor<6x8x8x8xf32>
    // 1 + exp(-x)
    %one = "stablehlo.constant"() {value = dense<1.0 : f32>} : () -> tensor<1xf32>
    %broadcast_one = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<1xf32>) -> tensor<6x8x8x8xf32>
    %denominator = "stablehlo.add"(%broadcast_one, %exp_neg_x) : (tensor<6x8x8x8xf32>, tensor<6x8x8x8xf32>) -> tensor<6x8x8x8xf32>
